  return null;
}

const toIsoDate = (raw) => parseDateSafe(raw);

return items.map((it) => ({
  json: {
    source_id: src.id,
    source_url: absolute(resolveUrl(cfg.url, it)),
    title_raw: String(dig(it, cfg.title) ?? ''),
    content_raw: String(dig(it, cfg.body) ?? ''),
    publication_date: toIsoDate(dig(it, cfg.date)),
    attachments: [],
    fetched_at: new Date().toISOString(),
  },
}));

// HTML lane → RawItem[]
//
// Selectors come from parser_config, which an admin filled in against the
// live page during verification. A source with an empty config cannot be
// marked verified and therefore cannot be active, so this never runs on
// guessed selectors.

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};

// Extract origin without using the URL class,
// because this n8n environment does not expose it inside Code nodes.
const baseUrl = String(src.base_url || '').replace(/\/+$/, '');
const originMatch = baseUrl.match(/^(https?:\/\/[^/]+)/i);
const origin = originMatch ? originMatch[1] : baseUrl;

// Optional secondary split for a `list` match that has no per-item wrapper
// at all — the repeating unit IS a bare tag (e.g. LMRA Bahrain: 10 sibling
// <a class="list-group-item" href=... title=...> elements with no shared
// per-item parent). `list` still matches the one real shared ancestor (e.g.
// the surrounding <div class="list-group">); `list_item` (a bare tag name,
// e.g. "a") then splits that single blob into each top-level <a>...</a>
// fragment, keeping every fragment's OWN opening tag intact — unlike the
// native listing extractor (which returns only a matched element's INNER
// html), this preserves the row's own attributes (href, title, ...) so
// pick(row, 'a@href') / pick(row, 'a@title') can read them directly off the
// row itself. Only used when parser_config.list_item is set — every source
// without it keeps exactly the current single-block-per-list-match shape.
const splitListItem = (html, tag) => {
  const tokenRe = new RegExp(`<${tag}(?:\\s[^>]*)?>|</${tag}>`, 'gi');
  const stack = [];
  const results = [];
  let m;
  while ((m = tokenRe.exec(html))) {
    const isOpen = m[0][0] === '<' && m[0][1] !== '/';
    if (isOpen) {
      stack.push(m.index);
    } else {
      const start = stack.pop();
      if (start === undefined) continue;
      if (stack.length === 0) results.push(html.slice(start, m.index + m[0].length));
    }
  }
  return results;
};

const rawBlocks = $input.first().json.items || [];
const blocks = cfg.list_item
  ? rawBlocks.flatMap((block) => splitListItem(block, cfg.list_item))
  : rawBlocks;

// Minimal extraction over the fragment HTML. Kept dependency-free: the
// HTML node has already narrowed the document to the list items.
const pick = (html, selector) => {
  if (!selector) return '';

  // Optional trailing occurrence index — "span:2" is the 2nd <span> found in
  // the fragment (see below), 1 unless stated, never assumed. Always the
  // outermost suffix, so it applies the same whether or not "@attr" is also
  // present ("a@href:2" means the 2nd <a>'s href).
  const idxMatch = selector.match(/^(.*):(\d+)$/);
  const withoutIdx = idxMatch ? idxMatch[1] : selector;
  const occurrence = idxMatch ? Math.max(1, Number(idxMatch[2])) : 1;

  const attrMatch = withoutIdx.match(/^(.*)@([\w-]+)$/);
  const sel = (attrMatch ? attrMatch[1] : withoutIdx).trim();
  const attr = attrMatch ? attrMatch[2] : null;

  // Optional "tag#substring" targets whichever <tag> has an id CONTAINING
  // that substring — ASP.NET/WebForms pages routinely prefix a real id with
  // a long, template-generated control path (e.g. "ctl00_ctl32_..._ItemDate"),
  // so a substring match is the part that's actually stable page to page.
  const idMatch = sel.match(/^([a-zA-Z][\w-]*)#(.+)$/);
  const tag = (idMatch ? idMatch[1] : sel.split(/[\s>]/).pop().replace(/[.#].*$/, '')) || 'a';
  const idSubstring = idMatch ? idMatch[2] : null;

  const idOf = (attrs) => {
    const m = attrs.match(/\sid=["']([^"']*)["']/i);
    return m ? m[1] : '';
  };

  if (attr) {
    // Attribute extraction only ever needs the *opening* tag, so this never
    // requires a matching close — mirrors the old behaviour exactly (the
    // first tag that actually carries this attribute) when no :N/#id is
    // given, and extends it with the same occurrence/id targeting.
    const openRe = new RegExp(`<${tag}(\\s[^>]*)?>`, 'gi');
    let count = 0, m;
    while ((m = openRe.exec(html))) {
      const attrs = m[1] || '';
      if (idSubstring && !idOf(attrs).includes(idSubstring)) continue;
      if (!new RegExp(`\\s${attr}=["']`, 'i').test(attrs)) continue;
      count++;
      if (count === occurrence) {
        const av = attrs.match(new RegExp(`\\s${attr}=["']([^"']+)["']`, 'i'));
        return av ? av[1] : '';
      }
    }
    return '';
  }

  // Finds the Nth complete <tag>...</tag> pair, tracking a same-tag depth
  // stack so a wrapper that itself contains other <tag> elements resolves to
  // its OWN matching close, not the nearest one anywhere after it (the old
  // single non-greedy regex effectively did the latter, which silently
  // truncated content whenever the same tag nested inside itself — the SAIP
  // media-center publish date, reached only through two other <div>
  // wrappers, is a real case this fixes). Occurrences are numbered in the
  // order each pair *closes*, so an innermost/leaf element — normally what a
  // config is actually reaching for — gets a low number regardless of how
  // deep it sits; a flat run of siblings with no nesting at all numbers
  // exactly as simple top-to-bottom counting would expect (unchanged from
  // the old behaviour for occurrence 1 with no nesting).
  const tokenRe = new RegExp(`<${tag}(\\s[^>]*)?>|</${tag}>`, 'gi');
  const stack = [];
  let count = 0, m, found = null;
  while ((m = tokenRe.exec(html))) {
    const isOpen = m[0][0] === '<' && m[0][1] !== '/';
    if (isOpen) {
      stack.push({ start: m.index + m[0].length, attrs: m[1] || '' });
    } else {
      const frame = stack.pop();
      if (!frame) continue;
      if (idSubstring && !idOf(frame.attrs).includes(idSubstring)) continue;
      count++;
      if (count === occurrence) { found = { attrs: frame.attrs, inner: html.slice(frame.start, m.index) }; break; }
    }
  }
  if (!found) return '';

  if (tag === 'time') {
    const dt = found.attrs.match(/\sdatetime=["']([^"']+)["']/i);
    if (dt) return dt[1];
  }

  return found.inner.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
};

const absolute = (href) => {
  const value = String(href || '').trim();
  if (!value) return '';
  if (/^https?:\/\//i.test(value)) return value;
  if (value.startsWith('//')) return `https:${value}`;
  if (value.startsWith('/')) return `${origin}${value}`;
  return `${baseUrl}/${value.replace(/^\/+/, '')}`;
};

// ── parseDateSafe ──────────────────────────────────────────────────────
// Deterministic replacement for new Date(raw). new Date() silently
// misreads ambiguous day-first dates (e.g. "05/08/2026", meant 5 August,
// becomes 8 May under its US-style MM/DD heuristic) and cannot parse
// Arabic month names or Hijri dates at all — confirmed empirically during
// the 2026-08-10 source-verification pass across every candidate source.
// Every source this platform crawls is an Arabic/Gulf official site, so
// when a numeric date's day/month order is ambiguous (both values <= 12)
// this function always assumes DAY-FIRST (DD/MM/YYYY) — a fixed rule, not
// a per-string guess. Hijri dates are recognised (by month name or a
// "هـ"/"هجري" marker) but never converted: no Hijri→Gregorian algorithm in
// this project is verified against the real Umm al-Qura calendar these
// sites use, and an approximate conversion could be silently off by a
// day — exactly the failure mode this function exists to prevent.
// Anything it cannot resolve with certainty returns null; the caller
// never invents a date, and legal_updates.publication_date is NOT NULL,
// so null here always means "the Publishing Gate skips this item", never
// a bad insert.
function parseDateSafe(raw) {
  if (raw === null || raw === undefined) return null;
  const EASTERN_DIGITS = '٠١٢٣٤٥٦٧٨٩';
  let text = String(raw).trim().replace(/[٠-٩]/g, (ch) => String(EASTERN_DIGITS.indexOf(ch)));
  if (!text) return null;

  const pad = (n) => String(n).padStart(2, '0');
  const daysInMonth = (y, m) => new Date(Date.UTC(y, m, 0)).getUTCDate();
  const isValid = (y, m, d) => m >= 1 && m <= 12 && d >= 1 && d <= daysInMonth(y, m);
  const iso = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;

  const HIJRI_MONTHS = ['محرم', 'صفر', 'ربيع الأول', 'ربيع الآخر', 'ربيع الثاني', 'جمادى الأولى', 'جمادى الآخرة', 'جمادى الثاني', 'رجب', 'شعبان', 'رمضان', 'شوال', 'ذو القعدة', 'ذو الحجة'];
  const hasHijriSignal = (s) => HIJRI_MONTHS.some((m) => s.includes(m)) || /هـ|هجري|\bAH\b/i.test(s);

  // Dual-calendar strings ("16/04/2026 الموافق 28/10/1447 هجري") pair a real
  // Gregorian date with its Hijri equivalent via the connector "الموافق"
  // ("corresponding to") — confirmed on Al-Meezan (Qatar), both on its law
  // detail page's issuance date and publication date fields. When a Hijri
  // signal appears strictly after that connector, only the text before it is
  // eligible for Gregorian parsing below, so the real date is not thrown
  // away by the Hijri guard. A bare Hijri date with no such connector (e.g.
  // "10 أغسطس 1448 هـ", where "أغسطس" is a coincidental look-alike, not a
  // second calendar) never contains "الموافق" and is untouched — still
  // resolves to null via the guard exactly as before.
  const connectorIdx = text.indexOf('الموافق');
  if (connectorIdx !== -1 && hasHijriSignal(text.slice(connectorIdx))) {
    text = text.slice(0, connectorIdx);
  }

  // 1) ISO date or datetime — YYYY-MM-DD, optionally with a time part.
  const isoMatch = text.match(/\b(\d{4})-(\d{2})-(\d{2})(?:[T ][\d:.,+Zz-]*)?/);
  if (isoMatch) {
    const y = Number(isoMatch[1]), m = Number(isoMatch[2]), d = Number(isoMatch[3]);
    return isValid(y, m, d) ? iso(y, m, d) : null;
  }

  // 2) Hijri guard — recognised, never converted (see header comment).
  if (hasHijriSignal(text)) return null;

  // 3) Arabic Gregorian month names — "10 أغسطس 2026" / "05-أغسطس-2026".
  const AR_MONTHS = { 'يناير': 1, 'فبراير': 2, 'مارس': 3, 'أبريل': 4, 'إبريل': 4, 'مايو': 5, 'يونيو': 6, 'يوليو': 7, 'أغسطس': 8, 'سبتمبر': 9, 'أكتوبر': 10, 'نوفمبر': 11, 'ديسمبر': 12 };
  const arMonthNames = Object.keys(AR_MONTHS).sort((a, b) => b.length - a.length).join('|');
  const arMatch = text.match(new RegExp(`(\\d{1,2})\\s*[-\\s]\\s*(${arMonthNames})\\s*[-\\s]\\s*(\\d{4})`));
  if (arMatch) {
    const d = Number(arMatch[1]), m = AR_MONTHS[arMatch[2]], y = Number(arMatch[3]);
    return isValid(y, m, d) ? iso(y, m, d) : null;
  }

  // 4) English month names — "August 5, 2026" / "5 August 2026" /
  // "05 Aug 2026" / RFC-822 ("Wed, 05 Aug 2026 10:00:00 GMT").
  const EN_MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
  const enMonthNames = 'january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sept|sep|oct|nov|dec';
  const dayFirst = text.match(new RegExp(`\\b(\\d{1,2})\\s+(${enMonthNames})\\.?,?\\s+(\\d{4})\\b`, 'i'));
  const monthFirst = !dayFirst && text.match(new RegExp(`\\b(${enMonthNames})\\.?\\s+(\\d{1,2}),?\\s+(\\d{4})\\b`, 'i'));
  if (dayFirst || monthFirst) {
    const d = Number(dayFirst ? dayFirst[1] : monthFirst[2]);
    const monthWord = (dayFirst ? dayFirst[2] : monthFirst[1]).toLowerCase();
    const m = EN_MONTHS[monthWord.slice(0, 3)];
    const y = Number(dayFirst ? dayFirst[3] : monthFirst[3]);
    return m && isValid(y, m, d) ? iso(y, m, d) : null;
  }

  // 5) Numeric day-first — DD/MM/YYYY, DD-MM-YYYY, or DD.MM.YYYY (the dot
  // form is real: SAIP's media-center listing uses "09.07.2026"). First
  // number is always the day, second is always the month (see header
  // comment) — never inferred from magnitude, so "08/10/2026" is always 8
  // Oct, not a guess, and label text before the numbers (e.g. "القرارات
  // 10/08/2026") does not block the match.
  const numMatch = text.match(/\b(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})\b/);
  if (numMatch) {
    const d = Number(numMatch[1]), m = Number(numMatch[2]), y = Number(numMatch[3]);
    return isValid(y, m, d) ? iso(y, m, d) : null;
  }

  return null;
}

const toIsoDate = (raw) => parseDateSafe(raw);

return blocks.map((html) => {
  const link = absolute(pick(html, cfg.link));
  const pdfMatch = html.match(/href=["']([^"']+\.pdf)["']/i);
  return {
    json: {
      source_id: src.id,
      source_url: link,
      title_raw: pick(html, cfg.title),
      content_raw: pick(html, cfg.body),
      publication_date: toIsoDate(pick(html, cfg.date)),
      // PDF enrichment applies to every lane, not just parser_type = pdf:
      // gazettes routinely publish a listing entry whose substance is an
      // attached document.
      attachments: pdfMatch ? [absolute(pdfMatch[1])] : [],
      fetched_at: new Date().toISOString(),
    },
  };
});

const src = $('Called by scheduler').first().json.source;
const cfg = src.parser_config || {};
const maxPages = Number(cfg.max_pages) || 40;

const baseUrl = String(src.base_url || '').replace(/\/+$/, '');
const originMatch = baseUrl.match(/^(https?:\/\/[^/]+)/i);
const origin = originMatch ? originMatch[1] : baseUrl;

const makeAbsolute = (href) => {
  const value = String(href || '').trim();

  if (!value) return '';
  if (/^https?:\/\//i.test(value)) return value;
  if (value.startsWith('//')) return `https:${value}`;
  if (value.startsWith('/')) return `${origin}${value}`;

  return `${baseUrl}/${value.replace(/^\/+/, '')}`;
};

const input = $input.first().json;

const html =
  typeof input.data === 'string'
    ? input.data
    : typeof input.body === 'string'
      ? input.body
      : '';

const links = [...html.matchAll(
  /href=["']([^"']+\.pdf(?:\?[^"']*)?)["'][^>]*>([\s\S]*?)</gi
)]
  .slice(0, maxPages)
  .map((match) => ({
    href: makeAbsolute(match[1]),
    label: match[2]
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim(),
  }))
  .filter((link) => link.href);

return links.map((link) => ({
  json: {
    source_id: src.id,
    source_url: link.href,
    title_raw: link.label || 'عدد من الجريدة الرسمية أم القرى',
    content_raw: '',
    publication_date: null,
    attachments: [link.href],
    fetched_at: new Date().toISOString(),
  },
}));

// Normalises and validates every RawItem before anything downstream sees it.
//
// This is the single contract between parsing and the M9 AI stage: whatever
// lane produced an item, it leaves here in the same shape or not at all.

const src = $('Called by scheduler').first().json.source;

const allowed = (src.allowed_domains || [])
  .map((domain) => String(domain).trim().toLowerCase())
  .filter(Boolean);

const out = [];
const rejected = {
  no_url: 0,
  no_title: 0,
  domain_mismatch: 0,
  out_of_window: 0,
};

// Manual catch-up refreshes (Workflow 04) carry a window_from on the trigger
// payload — everything before it is redundant with a prior successful run.
// Absent for any other caller, so this is a no-op outside the catch-up path.
const windowFrom = $('Called by scheduler').first().json.window_from || null;
const windowFromDate = windowFrom ? String(windowFrom).slice(0, 10) : null;

for (const item of $input.all()) {
  const r = item.json;

  const sourceUrl = String(r.source_url || '').trim();
  const titleRaw = String(r.title_raw || '').trim();

  if (!sourceUrl) {
    rejected.no_url += 1;
    continue;
  }

  if (!titleRaw) {
    rejected.no_title += 1;
    continue;
  }

  // Extract hostname without using the URL class,
  // because this n8n environment does not expose it inside Code nodes.
  const hostMatch = sourceUrl.match(/^https?:\/\/([^/:?#]+)/i);

  if (!hostMatch) {
    rejected.no_url += 1;
    continue;
  }

  const host = hostMatch[1].toLowerCase();

  // A discovery pseudo-source's own allow-list (news.google.com) describes
  // ITS domain, not the real-world domain a discovered item resolved to.
  // That resolution already happened in Workflow 05 (matched against a real
  // official source's allow-list, or left as discovery on purpose); the
  // Publishing Gate re-applies the same bypass at publish time. Re-checking
  // a fixed allow-list here would reject every genuine discovery find.
  const isDiscoverySource = src.ingestion_mode === 'discovery';
  if (!isDiscoverySource && !allowed.includes(host)) {
    rejected.domain_mismatch += 1;
    continue;
  }

  // Catch-up windowing: an item with a known publication date older than
  // the run's window is redundant with what a prior successful run (or this
  // one's overlap) already covered. An item with NO date is never rejected
  // here — the Publishing Gate's own no_publication_date rule handles it.
  if (windowFromDate && r.publication_date && r.publication_date < windowFromDate) {
    rejected.out_of_window += 1;
    continue;
  }

  out.push({
    json: {
      source_id: src.id,
      source_url: sourceUrl,
      title_raw: titleRaw.slice(0, 2000),
      content_raw: String(r.content_raw || '').trim().slice(0, 50000),
      publication_date: r.publication_date || null,
      attachments: Array.isArray(r.attachments)
        ? r.attachments.slice(0, 5)
        : [],
      fetched_at: r.fetched_at || new Date().toISOString(),
      // M13 hybrid discovery — absent (undefined) on every official-lane
      // item, so it defaults through Workflow 03 exactly as before.
      origin_type: r.origin_type || undefined,
      canonical_url: r.canonical_url || undefined,
      discovery_engine: r.discovery_engine || undefined,

      // Carried through so M9 can log against the correct source.
      source: {
        id: src.id,
        country: src.country,
        authority_ar: src.authority_ar,
        allowed_domains: src.allowed_domains,
        ingestion_mode: src.ingestion_mode,
      },
    },
  });
}

console.log(
  `normalised ${out.length} items; rejected ${JSON.stringify(rejected)}`
);

// A genuinely empty result must still leave exactly one item behind, or every
// downstream node (including the log write) is skipped by n8n's zero-item rule
// and the run vanishes without a workflow_logs row or a webhook response.
if (out.length === 0) {
  return [{ json: { __empty: true, raw_count: $input.all().length, rejected } }];
}

// M9 attaches the AI stage and the Publishing Gate to this output.
return out;

// Fetch failure for this source.
//
// Isolated on purpose: one unreachable source must not stop the others in the
// same scheduler tick. M10 turns this into retry state and a health snapshot;
// for now it records the failure and ends this source's run.

const src = $('Called by scheduler').first().json.source;
const err = $input.first().json.error || $input.first().json;

return [{
  json: {
    failed: true,
    source_id: src.id,
    authority_ar: src.authority_ar,
    error_message: String(err?.message || err?.reason || 'fetch failed').slice(0, 1000),
  },
}];

parameters.jsonBody:
={{ JSON.stringify({ messages: [{ role: 'system', content: $json.system_prompt }, { role: 'user', content: `الجهة: ${$json.source.authority_ar}
الدولة المسجّلة للمصدر: ${$json.source.country}
الرابط: ${$json.source_url}
تاريخ النشر المستخرج من المصدر: ${$json.publication_date || 'غير متوفر'}

العنوان:
${$json.title_raw}

النص:
${$json.content_raw}` }], response_format: { type: 'json_object' } }) }}

parameters.jsCode:
// Carries the RawItem alongside the AI response so the validator can pair
// them. itemMatching follows n8n's own pairedItem lineage back to the
// source item rather than assuming position N in equals position N out.
const out = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  const original = $('Classification prompt').itemMatching(i).json;
  out.push({ json: { ...inputs[i].json, __item: original } });
}
return out;

// Parses and validates the model's JSON. FAIL CLOSED.
//
// Anything malformed, incomplete, or outside the allowed enums is rejected
// outright — never coerced, never defaulted. A coerced category would put a
// confident wrong classification in a legal archive, which is worse than a gap.
//
// Azure's output contract: is_legal_update, title, summary, category,
// country, document_type, legal_status, gcc_relevant. There is no
// confidence score and no threshold — a false classification is rejected
// here at the schema level, and anything the model marks true is stored.
// document_type/legal_status were re-enabled here (previously hardcoded to
// null) once category alone proved unable to distinguish "what kind of
// instrument" (new law vs. amendment vs. ministerial decision vs. court
// ruling) from "which practice area" (tax, litigation...) — the two are
// independent axes, never inferred from one another. gcc_relevant is a
// separate, dedicated field (never inferred from `country`) answering "is
// the legal actor itself Gulf-based" — added after a live incident where a
// discovery source's own registered country wrongly let US Congress and
// Turkish parliament news publish (see 03-publishing-gate.json Rule 4).
// effective_date/keywords/affected_entities are still not produced by the
// classifier; they stay null/empty on new rows (the columns remain, for the
// historical records that do have them).

const COUNTRY = ['SA','AE','KW','QA','BH','OM','GCC'];
const CATEGORY = ['tax','customs','employment','corporate','financial','capital_markets','banking','data_privacy','cybersecurity','competition','intellectual_property','litigation','licensing','real_estate','energy','healthcare','trade','general'];
const DOCUMENT_TYPE = ['law','royal_decree','ministerial_decision','executive_regulation','circular','regulatory_framework','official_notice','court_precedent','consultation_draft','other'];
const LEGAL_STATUS = ['enacted','effective','draft','amended','repealed','pending'];

const nonEmpty = (v) => typeof v === 'string' && v.trim().length > 0;

const out = [];

for (const entry of $input.all()) {
  const item = entry.json.__item;
  const response = entry.json;

  const fail = (reason, detail) => out.push({ json: {
    __item: item, __rejected: true, reason, detail: detail ? String(detail).slice(0,300) : null,
  }});

  // "Classify with AI" runs with n8n's own retryOnFail; a response that
  // still failed after those retries arrives here as an HTTP error status
  // rather than a body, via fullResponse + neverError.
  const status = typeof response?.statusCode === 'number' ? response.statusCode : null;
  if (status !== null && (status < 200 || status >= 300)) {
    fail('ai_http_error', JSON.stringify({ status, body: response?.body }).slice(0, 300));
    continue;
  }

  const body = status !== null ? response.body : response;
  const text = body?.choices?.[0]?.message?.content || '';

  if (body?.choices?.[0]?.finish_reason === 'length') {
    fail('ai_truncated_response', text || null);
    continue;
  }

  if (!nonEmpty(text)) {
    fail('ai_empty_response');
    continue;
  }

  let ai;
  try {
    ai = JSON.parse(text.trim());
  } catch {
    // One tolerated shape: the model wrapped the object in prose or a fence.
    const m = text.match(/\{[\s\S]*\}/);
    if (!m) { fail('ai_parse_failure', text); continue; }
    try { ai = JSON.parse(m[0]); } catch { fail('ai_parse_failure', text); continue; }
  }

  if (!ai || typeof ai !== 'object' || Array.isArray(ai)) { fail('ai_not_an_object'); continue; }

  if (typeof ai.is_legal_update !== 'boolean') { fail('ai_invalid_output', 'is_legal_update'); continue; }

  // An item the model itself says is not a legal update is rejected here —
  // "only reject obvious non-legal news" — never stored.
  if (ai.is_legal_update !== true) { fail('not_legal_update'); continue; }

  if (!nonEmpty(ai.title)) { fail('ai_invalid_output', 'title'); continue; }
  if (!nonEmpty(ai.summary)) { fail('ai_invalid_output', 'summary'); continue; }
  if (!COUNTRY.includes(ai.country)) { fail('ai_invalid_output', 'country=' + ai.country); continue; }
  if (!CATEGORY.includes(ai.category)) { fail('ai_invalid_output', 'category=' + ai.category); continue; }
  if (!DOCUMENT_TYPE.includes(ai.document_type)) { fail('ai_invalid_output', 'document_type=' + ai.document_type); continue; }
  // legal_status is the one field allowed to be null — "no clear evidence in
  // the text" is a normal, expected outcome, not a malformed response. A
  // non-null value still has to be one of the six real statuses, though:
  // anything else would fail the Postgres enum constraint on insert, which
  // is a worse failure mode than rejecting it here with a clear reason.
  if (ai.legal_status !== null && !LEGAL_STATUS.includes(ai.legal_status)) {
    fail('ai_invalid_output', 'legal_status=' + ai.legal_status);
    continue;
  }
  if (typeof ai.gcc_relevant !== 'boolean') { fail('ai_invalid_output', 'gcc_relevant'); continue; }

  out.push({ json: {
    __item: item,
    __rejected: false,
    ai: {
      title_ar: ai.title.trim(),
      summary_ar: ai.summary.trim(),
      country: ai.country,
      category: ai.category,
      document_type: ai.document_type,
      legal_status: ai.legal_status ?? null,
      gcc_relevant: ai.gcc_relevant,
      is_legal_update: true,
      confidence: null,
      publication_date: null,
      effective_date: null,
      affected_entities: [],
      keywords: [],
    },
  }});
}

return out;

// Builds the string that becomes content_hash, and drops items the AI stage
// already rejected.
//
// Hash inputs: source_id | source_url | title | publication_date. The URL is
// included deliberately — two authorities republishing the same instrument at
// different URLs are two archive entries, and the M3 exclusion-group rule
// handles the mirror case instead.

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (e.__rejected) { out.push({ json: e }); continue; }

  const item = e.__item;
  const pubDate = item.publication_date || e.ai.publication_date || '';

  out.push({ json: {
    ...e,
    hash_input: [item.source_id, item.source_url, e.ai.title_ar, pubDate].join('|'),
  }});
}
return out;

// Prepares the Publishing Gate payload.
//
// No confidence threshold to read: the AI's is_legal_update decision was
// already enforced in "Validate AI output" (a false there is a rejection,
// never reaches here), so this only shapes the item for the gate's
// remaining rules (source active/verified, domain allow-list, duplicate).

const out = [];
for (const entry of $input.all()) {
  const e = entry.json;
  if (e.__rejected) {
    // Rejected during AI-response validation: still needs source_id/content_hash
    // in the same `item` shape the gate expects, or the gate's source re-read
    // and hash lookup receive "undefined" and the Supabase call throws instead
    // of a clean rejection. The gate short-circuits on __rejected and never
    // reads `ai`, so it is left null rather than reconstructed.
    out.push({ json: {
      __rejected: true,
      reason: e.reason,
      detail: e.detail,
      ai: null,
      item: {
        source_id: e.__item.source_id,
        source_url: e.__item.source_url,
        content_hash: e.content_hash,
        publication_date: e.__item.publication_date,
        raw_excerpt: (e.__item.content_raw || e.__item.title_raw || '').slice(0, 20000),
        document_path: (e.__item.attachments && e.__item.attachments[0]) || null,
        ai_model: 'azure-openai',
      },
    }});
    continue;
  }

  const item = e.__item;
  out.push({ json: {
    __rejected: false,
    ai: e.ai,
    item: {
      source_id: item.source_id,
      source_url: item.source_url,
      content_hash: e.content_hash,
      publication_date: item.publication_date,
      // Verbatim source text, stored so a lawyer can check the summary against
      // what the authority actually published.
      raw_excerpt: (item.content_raw || item.title_raw || '').slice(0, 20000),
      // The official document URL, preserved end to end.
      document_path: (item.attachments && item.attachments[0]) || null,
      ai_model: 'azure-openai',
    },
  }});
}
return out;

// Aggregates every outcome for this source into ONE workflow_logs row.
//
// One row per source per run, not one per item: workflow_logs records
// executions, and the dashboard aggregates from it. Rejections are counted in
// rejection_reasons rather than logged individually — a rejection is a normal
// decision, not an incident.

const src = $('Called by scheduler').first().json.source;
const started = $('Called by scheduler').first().json.dispatched_at || new Date().toISOString();
const trigger = $('Called by scheduler').first().json.trigger_type || 'scheduled';
const correlationId = $('Called by scheduler').first().json.correlation_id || null;

let fetched = 0, published = 0, rejected = 0;
const reasons = {};
let errorMessage = null;

for (const entry of $input.all()) {
  const e = entry.json;
  fetched += 1;

  if (e.__rejected) {
    rejected += 1;
    reasons[e.reason] = (reasons[e.reason] || 0) + 1;
    continue;
  }
  if (e.outcome === 'published') { published += 1; continue; }
  if (e.outcome === 'duplicate') { rejected += 1; reasons.duplicate = (reasons.duplicate || 0) + 1; continue; }
  if (e.outcome === 'rejected') {
    rejected += 1;
    reasons[e.reason || 'unknown'] = (reasons[e.reason || 'unknown'] || 0) + 1;
    continue;
  }
  if (e.outcome === 'insert_failed') {
    rejected += 1;
    reasons.insert_failed = (reasons.insert_failed || 0) + 1;
    errorMessage = e.error_message || errorMessage;
  }
}

const finished = new Date().toISOString();

// partial: some items failed to insert. failed is reserved for a run that
// could not fetch at all, which the M10 failure branch records.
const status = errorMessage ? 'partial' : 'success';

return [{ json: {
  workflow_name: '02-source-ingestion',
  execution_id: String($execution.id),
  source_id: src.id,
  trigger_type: trigger,
  correlation_id: correlationId,
  status,
  items_fetched: fetched,
  items_published: published,
  items_rejected: rejected,
  rejection_reasons: reasons,
  error_message: errorMessage,
  duration_ms: Math.max(0, new Date(finished).getTime() - new Date(started).getTime()),
  retry_attempt: 0,
  started_at: started,
  finished_at: finished,
}}];

// Deliberate empty-run outcome: the source fetched cleanly but produced
// nothing normalisable (or everything was filtered by domain/shape). This
// is a successful run, logged as such, not silently dropped.
const src = $('Called by scheduler').first().json.source;
const started = $('Called by scheduler').first().json.dispatched_at || new Date().toISOString();
const trigger = $('Called by scheduler').first().json.trigger_type || 'scheduled';
const correlationId = $('Called by scheduler').first().json.correlation_id || null;
const marker = $input.first().json;
const finished = new Date().toISOString();

return [{ json: {
  workflow_name: '02-source-ingestion',
  execution_id: String($execution.id),
  source_id: src.id,
  trigger_type: trigger,
  correlation_id: correlationId,
  status: 'empty',
  items_fetched: marker.raw_count || 0,
  items_published: 0,
  items_rejected: 0,
  rejection_reasons: marker.rejected || {},
  error_message: null,
  duration_ms: Math.max(0, new Date(finished).getTime() - new Date(started).getTime()),
  retry_attempt: 0,
  started_at: started,
  finished_at: finished,
}}];

// A source that could not be fetched at all still needs a workflow_logs
// row (status='failed') and must not leave the webhook response hanging.
const started = $('Called by scheduler').first().json.dispatched_at || new Date().toISOString();
const trigger = $('Called by scheduler').first().json.trigger_type || 'scheduled';
const correlationId = $('Called by scheduler').first().json.correlation_id || null;
const e = $input.first().json;
const finished = new Date().toISOString();

return [{ json: {
  workflow_name: '02-source-ingestion',
  execution_id: String($execution.id),
  source_id: e.source_id,
  trigger_type: trigger,
  correlation_id: correlationId,
  status: 'failed',
  items_fetched: 0,
  items_published: 0,
  items_rejected: 0,
  rejection_reasons: {},
  error_message: e.error_message || 'fetch failed',
  duration_ms: Math.max(0, new Date(finished).getTime() - new Date(started).getTime()),
  retry_attempt: 0,
  started_at: started,
  finished_at: finished,
}}];

// Workflow 05 (Discovery Ingestion) already resolved and shaped these items
// — this just turns the ONE trigger item's prefetched_items array into
// separate n8n items, the same shape "Merge lanes" produces for an ordinary
// official-lane crawl, so Normalise RawItem treats both identically.
//
// Restored 2026-08-11: this step existed under the same name before the
// 2026-08-09 rewrite and was dropped when "Has prefetched items?" was wired
// straight to "Normalise RawItem". Normalise RawItem reads r.source_url
// etc. off each top-level $input item; without this step it instead saw
// ONE item shaped { source, prefetched_items: [...] }, so r.source_url was
// always undefined and every discovery item was rejected as no_url before
// ever reaching classification — confirmed live (2026-08-11 investigation)
// across every discovery source, 100% no_url, for every run since the
// rewrite.
const items = $('Called by scheduler').first().json.prefetched_items || [];
return items.map((it) => ({ json: it }));

// Opt-in, per-item detail-page date extraction — see "Needs detail-page
// date?" for the gate. Only ever runs for an item whose listing had no
// usable date AND whose source explicitly set parser_config.date_from_detail;
// every other source's items skip this branch entirely (no extra request).
//
// Tries structured signals first (most to least specific), falling back to
// parser_config.detail_date_selector — the same pick() mini-language used
// for listings — only when none of them are present on the page.

const cfg = $('Called by scheduler').first().json.source.parser_config || {};

// Extract date from detail page — tries structured signals first, in the
// order the platform's own listing metadata would be trusted (most to least
// specific), and only reaches for parser_config.detail_date_selector (the
// same pick() mini-language used for listings) if none of them are present.
const extractDetailDate = (html) => {
  // 1) JSON-LD — datePublished / dateCreated, anywhere in any <script
  // type="application/ld+json"> block, including a top-level array or an
  // @graph wrapper.
  const ldMatches = html.match(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi) || [];
  for (const block of ldMatches) {
    const jsonText = block.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, '');
    try {
      const parsed = JSON.parse(jsonText);
      const candidates = Array.isArray(parsed) ? parsed : (parsed['@graph'] || [parsed]);
      for (const node of candidates) {
        const v = node && (node.datePublished || node.dateCreated);
        if (v) return String(v);
      }
    } catch (e) {
      // Malformed JSON-LD on the page — not this extractor's problem to fix,
      // fall through to the next signal.
    }
  }

  // 2) Meta tags — the common published-date variants, tried in order.
  const metaNames = [
    'article:published_time',
    'article:modified_time',
    'og:updated_time',
    'datePublished',
    'date',
  ];
  for (const name of metaNames) {
    const re = new RegExp(`<meta[^>]*(?:property|name)=["']${name}["'][^>]*content=["']([^"']+)["']`, 'i');
    const m = html.match(re) || html.match(new RegExp(`<meta[^>]*content=["']([^"']+)["'][^>]*(?:property|name)=["']${name}["']`, 'i'));
    if (m) return m[1];
  }

  // 3) <time datetime="...">
  const dt = html.match(/<time[^>]*\sdatetime=["']([^"']+)["']/i);
  if (dt) return dt[1];

  return null;
};

const pick = (html, selector) => {
  if (!selector) return '';

  // Optional trailing occurrence index — "span:2" is the 2nd <span> found in
  // the fragment (see below), 1 unless stated, never assumed. Always the
  // outermost suffix, so it applies the same whether or not "@attr" is also
  // present ("a@href:2" means the 2nd <a>'s href).
  const idxMatch = selector.match(/^(.*):(\d+)$/);
  const withoutIdx = idxMatch ? idxMatch[1] : selector;
  const occurrence = idxMatch ? Math.max(1, Number(idxMatch[2])) : 1;

  const attrMatch = withoutIdx.match(/^(.*)@([\w-]+)$/);
  const sel = (attrMatch ? attrMatch[1] : withoutIdx).trim();
  const attr = attrMatch ? attrMatch[2] : null;

  // Optional "tag#substring" targets whichever <tag> has an id CONTAINING
  // that substring — ASP.NET/WebForms pages routinely prefix a real id with
  // a long, template-generated control path (e.g. "ctl00_ctl32_..._ItemDate"),
  // so a substring match is the part that's actually stable page to page.
  const idMatch = sel.match(/^([a-zA-Z][\w-]*)#(.+)$/);
  const tag = (idMatch ? idMatch[1] : sel.split(/[\s>]/).pop().replace(/[.#].*$/, '')) || 'a';
  const idSubstring = idMatch ? idMatch[2] : null;

  const idOf = (attrs) => {
    const m = attrs.match(/\sid=["']([^"']*)["']/i);
    return m ? m[1] : '';
  };

  if (attr) {
    // Attribute extraction only ever needs the *opening* tag, so this never
    // requires a matching close — mirrors the old behaviour exactly (the
    // first tag that actually carries this attribute) when no :N/#id is
    // given, and extends it with the same occurrence/id targeting.
    const openRe = new RegExp(`<${tag}(\\s[^>]*)?>`, 'gi');
    let count = 0, m;
    while ((m = openRe.exec(html))) {
      const attrs = m[1] || '';
      if (idSubstring && !idOf(attrs).includes(idSubstring)) continue;
      if (!new RegExp(`\\s${attr}=["']`, 'i').test(attrs)) continue;
      count++;
      if (count === occurrence) {
        const av = attrs.match(new RegExp(`\\s${attr}=["']([^"']+)["']`, 'i'));
        return av ? av[1] : '';
      }
    }
    return '';
  }

  // Finds the Nth complete <tag>...</tag> pair, tracking a same-tag depth
  // stack so a wrapper that itself contains other <tag> elements resolves to
  // its OWN matching close, not the nearest one anywhere after it (the old
  // single non-greedy regex effectively did the latter, which silently
  // truncated content whenever the same tag nested inside itself — the SAIP
  // media-center publish date, reached only through two other <div>
  // wrappers, is a real case this fixes). Occurrences are numbered in the
  // order each pair *closes*, so an innermost/leaf element — normally what a
  // config is actually reaching for — gets a low number regardless of how
  // deep it sits; a flat run of siblings with no nesting at all numbers
  // exactly as simple top-to-bottom counting would expect (unchanged from
  // the old behaviour for occurrence 1 with no nesting).
  const tokenRe = new RegExp(`<${tag}(\\s[^>]*)?>|</${tag}>`, 'gi');
  const stack = [];
  let count = 0, m, found = null;
  while ((m = tokenRe.exec(html))) {
    const isOpen = m[0][0] === '<' && m[0][1] !== '/';
    if (isOpen) {
      stack.push({ start: m.index + m[0].length, attrs: m[1] || '' });
    } else {
      const frame = stack.pop();
      if (!frame) continue;
      if (idSubstring && !idOf(frame.attrs).includes(idSubstring)) continue;
      count++;
      if (count === occurrence) { found = { attrs: frame.attrs, inner: html.slice(frame.start, m.index) }; break; }
    }
  }
  if (!found) return '';

  if (tag === 'time') {
    const dt = found.attrs.match(/\sdatetime=["']([^"']+)["']/i);
    if (dt) return dt[1];
  }

  return found.inner.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
};

function parseDateSafe(raw) {
  if (raw === null || raw === undefined) return null;
  const EASTERN_DIGITS = '٠١٢٣٤٥٦٧٨٩';
  let text = String(raw).trim().replace(/[٠-٩]/g, (ch) => String(EASTERN_DIGITS.indexOf(ch)));
  if (!text) return null;

  const pad = (n) => String(n).padStart(2, '0');
  const daysInMonth = (y, m) => new Date(Date.UTC(y, m, 0)).getUTCDate();
  const isValid = (y, m, d) => m >= 1 && m <= 12 && d >= 1 && d <= daysInMonth(y, m);
  const iso = (y, m, d) => `${y}-${pad(m)}-${pad(d)}`;

  const HIJRI_MONTHS = ['محرم', 'صفر', 'ربيع الأول', 'ربيع الآخر', 'ربيع الثاني', 'جمادى الأولى', 'جمادى الآخرة', 'جمادى الثاني', 'رجب', 'شعبان', 'رمضان', 'شوال', 'ذو القعدة', 'ذو الحجة'];
  const hasHijriSignal = (s) => HIJRI_MONTHS.some((m) => s.includes(m)) || /هـ|هجري|\bAH\b/i.test(s);

  // Dual-calendar strings ("16/04/2026 الموافق 28/10/1447 هجري") pair a real
  // Gregorian date with its Hijri equivalent via the connector "الموافق"
  // ("corresponding to") — confirmed on Al-Meezan (Qatar), both on its law
  // detail page's issuance date and publication date fields. When a Hijri
  // signal appears strictly after that connector, only the text before it is
  // eligible for Gregorian parsing below, so the real date is not thrown
  // away by the Hijri guard. A bare Hijri date with no such connector (e.g.
  // "10 أغسطس 1448 هـ", where "أغسطس" is a coincidental look-alike, not a
  // second calendar) never contains "الموافق" and is untouched — still
  // resolves to null via the guard exactly as before.
  const connectorIdx = text.indexOf('الموافق');
  if (connectorIdx !== -1 && hasHijriSignal(text.slice(connectorIdx))) {
    text = text.slice(0, connectorIdx);
  }

  // 1) ISO date or datetime — YYYY-MM-DD, optionally with a time part.
  const isoMatch = text.match(/\b(\d{4})-(\d{2})-(\d{2})(?:[T ][\d:.,+Zz-]*)?/);
  if (isoMatch) {
    const y = Number(isoMatch[1]), m = Number(isoMatch[2]), d = Number(isoMatch[3]);
    return isValid(y, m, d) ? iso(y, m, d) : null;
  }

  // 2) Hijri guard — recognised, never converted (see header comment).
  if (hasHijriSignal(text)) return null;

  // 3) Arabic Gregorian month names — "10 أغسطس 2026" / "05-أغسطس-2026".
  const AR_MONTHS = { 'يناير': 1, 'فبراير': 2, 'مارس': 3, 'أبريل': 4, 'إبريل': 4, 'مايو': 5, 'يونيو': 6, 'يوليو': 7, 'أغسطس': 8, 'سبتمبر': 9, 'أكتوبر': 10, 'نوفمبر': 11, 'ديسمبر': 12 };
  const arMonthNames = Object.keys(AR_MONTHS).sort((a, b) => b.length - a.length).join('|');
  const arMatch = text.match(new RegExp(`(\\d{1,2})\\s*[-\\s]\\s*(${arMonthNames})\\s*[-\\s]\\s*(\\d{4})`));
  if (arMatch) {
    const d = Number(arMatch[1]), m = AR_MONTHS[arMatch[2]], y = Number(arMatch[3]);
    return isValid(y, m, d) ? iso(y, m, d) : null;
  }

  // 4) English month names — "August 5, 2026" / "5 August 2026" /
  // "05 Aug 2026" / RFC-822 ("Wed, 05 Aug 2026 10:00:00 GMT").
  const EN_MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
  const enMonthNames = 'january|february|march|april|may|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sept|sep|oct|nov|dec';
  const dayFirst = text.match(new RegExp(`\\b(\\d{1,2})\\s+(${enMonthNames})\\.?,?\\s+(\\d{4})\\b`, 'i'));
  const monthFirst = !dayFirst && text.match(new RegExp(`\\b(${enMonthNames})\\.?\\s+(\\d{1,2}),?\\s+(\\d{4})\\b`, 'i'));
  if (dayFirst || monthFirst) {
    const d = Number(dayFirst ? dayFirst[1] : monthFirst[2]);
    const monthWord = (dayFirst ? dayFirst[2] : monthFirst[1]).toLowerCase();
    const m = EN_MONTHS[monthWord.slice(0, 3)];
    const y = Number(dayFirst ? dayFirst[3] : monthFirst[3]);
    return m && isValid(y, m, d) ? iso(y, m, d) : null;
  }

  // 5) Numeric day-first — DD/MM/YYYY, DD-MM-YYYY, or DD.MM.YYYY (the dot
  // form is real: SAIP's media-center listing uses "09.07.2026"). First
  // number is always the day, second is always the month (see header
  // comment) — never inferred from magnitude, so "08/10/2026" is always 8
  // Oct, not a guess, and label text before the numbers (e.g. "القرارات
  // 10/08/2026") does not block the match.
  const numMatch = text.match(/\b(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})\b/);
  if (numMatch) {
    const d = Number(numMatch[1]), m = Number(numMatch[2]), y = Number(numMatch[3]);
    return isValid(y, m, d) ? iso(y, m, d) : null;
  }

  return null;
}

// Runs once for the whole batch (not per item) like every other lane node
// in this workflow, looping explicitly so a source with N items awaiting a
// detail-page date actually gets all N processed, not just the first.
return $input.all().map((item, i) => {
  const original = $('Normalise RawItem').itemMatching(i).json;
  const html = item.json.data || '';
  let extracted = extractDetailDate(html);
  if (!extracted && cfg.detail_date_selector) {
    extracted = pick(html, cfg.detail_date_selector);
  }
  return {
    json: {
      ...original,
      publication_date: parseDateSafe(extracted) || original.publication_date,
    },
  };
});

// The detail-page fetch itself failed (network error, non-200, timeout) —
// this must never fail the item. It already had no date before this branch
// was entered, so it simply continues with the date it already had (null),
// exactly as if parser_config.date_from_detail were not set at all.
return $input.all().map((item, i) => ({ json: $('Normalise RawItem').itemMatching(i).json }));
